namespace {int allocate_after=-1;}
void* operator new(std::size_t n){if(allocate_after==0){allocate_after=-1;throw std::bad_alloc();}if(allocate_after>0)--allocate_after;if(auto* p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void operator delete(void* p) noexcept {std::free(p);}void operator delete(void* p,std::size_t) noexcept {std::free(p);}
namespace {
using Bytes=std::vector<std::uint8_t>;using E=MovieUserdataRetentionError;
void check(bool v,const char* why){if(!v)throw std::runtime_error(why);}
MovieHeaderUnit userdata(const Bytes& body){Bytes b{0,0,1,0xb2};b.insert(b.end(),body.begin(),body.end());b.insert(b.end(),{0,0,1,0xb7});auto p=parse_movie_header_unit(b);check(p.unit.has_value(),"literal whole B2");return std::move(*p.unit);}
MovieHeaderUnit coding(unsigned structure){
 // ID8, four f_code=1, DC0, explicit structure, all following flags0.
 Bytes b{0,0,1,0xb5,0x81,0x11,static_cast<std::uint8_t>(0x10|structure),0,0};
 auto p=parse_movie_header_unit(b);check(p.unit.has_value(),"literal parsed coding extension");return std::move(*p.unit);
}
struct Rig {
 std::shared_ptr<const MovieSourceObservationIdentity> id=std::make_shared<const MovieSourceObservationIdentity>();
 MovieUserdataRetentionFailure f;std::optional<NativeMovieUserdataRetention> owner;
 explicit Rig(bool bound=true){owner=NativeMovieUserdataRetention::create("key",id,bound,f);check(owner.has_value(),"explicit identity and destination");}
 MovieUserdataRetentionState state(){auto s=owner->snapshot(f);check(s.has_value(),"owned snapshot");return *s;}
 void code(unsigned structure){check(owner->coding_extension("key",id,coding(structure),f),"actual coding event");}
 void put(const MovieHeaderUnit& b,MovieUserdataPrimaryKind k=MovieUserdataPrimaryKind::picture){check(owner->append("key",id,k,b,f),"validated B2 event");}
 void bound(bool b){check(owner->set_bound("key",id,b,f),"explicit destination binding");}
};
const Bytes sep{0,0,1,0xb2,0x32,0x6e,0x64,0};
}
int main(){try{
 static_assert(!std::is_default_constructible_v<NativeMovieUserdataRetention>);static_assert(!std::is_copy_constructible_v<NativeMovieUserdataRetention>);
 const auto a=userdata({0x41,0x80}),b=userdata({0x42});
 {Rig r;auto initial=r.state();check(initial.source_key=="key"&&initial.identity==r.id&&initial.bound&&!initial.phase&&!initial.field_counter&&initial.bytes.empty(),"fresh scalar and byte state exactly zero");r.put(a);check(r.state().bytes==a.bytes,"whole B2 prefix retained");r.put(b);Bytes both=a.bytes;both.insert(both.end(),b.bytes.begin(),b.bytes.end());check(r.state().bytes==both,"multiple phase0 B2 append without implicit per-call clear");r.bound(false);check(r.state().bytes==both,"unbinding alone retains old used bytes");r.put(a);check(r.state().bytes==both,"unbound does not append");r.bound(true);check(r.state().bytes==both,"rebinding same owned destination does not create arbitrary buffer");for(auto k:{MovieUserdataPrimaryKind::initial,MovieUserdataPrimaryKind::sequence,MovieUserdataPrimaryKind::gop}){r.put(a,k);check(r.state().bytes==both,"nonpicture does not retain");}r.code(3);check(!r.state().phase&&!r.state().field_counter&&r.state().bytes.empty(),"frame structure clears count phase bytes");}
 {Rig r;r.code(1);check(r.state().field_counter==1&&!r.state().phase,"first field uses prior parity0");r.put(a);r.code(2);check(r.state().field_counter==2&&r.state().phase&&r.state().bytes==a.bytes,"second field preserves first bytes");r.put(b);Bytes expected=a.bytes;expected.insert(expected.end(),sep.begin(),sep.end());expected.insert(expected.end(),b.bytes.begin(),b.bytes.end());check(r.state().bytes==expected,"exact opaque separator before second-field B2");r.put(a);expected.insert(expected.end(),sep.begin(),sep.end());expected.insert(expected.end(),a.bytes.begin(),a.bytes.end());check(r.state().bytes==expected,"separator before every phase1 append");r.code(1);check(r.state().field_counter==3&&!r.state().phase&&r.state().bytes.empty(),"third event prior parity0 clears");r.code(3);check(!r.state().field_counter&&!r.state().phase,"frame reset after fields");}
 {Rig r(false);r.code(1);r.code(2);r.put(a);check(r.state().bytes.empty()&&r.state().phase,"phase evolves while unbound");r.bound(true);r.put(a);Bytes expected=sep;expected.insert(expected.end(),a.bytes.begin(),a.bytes.end());check(r.state().bytes==expected,"bind does not silently reset phase");r.bound(false);r.code(3);check(r.state().bytes.empty()&&!r.state().phase&&!r.state().bound,"coding clears independently of bound");}
 {Rig r;const auto large=userdata(Bytes(20000,0x5a));r.put(large);check(r.state().bytes==large.bytes&&r.state().bytes.size()==20004,"dynamic owned bytes beyond original0x800 and0x40");}
 {Rig r;r.put(a);auto before=r.state();auto foreign=std::make_shared<const MovieSourceObservationIdentity>();check(!r.owner->append("key",foreign,MovieUserdataPrimaryKind::picture,a,r.f)&&r.f.kind==E::foreign_source&&r.state()==before,"foreign same key epoch atomic");check(!r.owner->coding_extension("other",r.id,coding(3),r.f)&&r.f.kind==E::foreign_source&&r.state()==before,"foreign key cannot clear");check(!r.owner->set_bound("key",{},false,r.f)&&r.f.kind==E::foreign_source&&r.state()==before,"missing identity cannot unbind");check(!r.owner->append("key",r.id,static_cast<MovieUserdataPrimaryKind>(99),a,r.f)&&r.f.kind==E::invalid_kind&&r.state()==before,"invalid kind before mutation");
  for(unsigned bad=0;bad<5;++bad){auto u=a;if(bad==0)++u.consumed_bytes;if(bad==1)u.bytes[3]=0xb3;if(bad==2)std::get<MovieUserDataHeader>(u.payload).payload[0]^=1;if(bad==3){u.bytes.insert(u.bytes.end(),{0,0,1});u.consumed_bytes=u.bytes.size();auto& body=std::get<MovieUserDataHeader>(u.payload).payload;body.insert(body.end(),{0,0,1});}if(bad==4)u.payload=MovieSequenceEndHeader{};check(!r.owner->append("key",r.id,MovieUserdataPrimaryKind::picture,u,r.f)&&r.f.kind==E::invalid_unit&&r.state()==before,"forged B2 rejected atomic");}
  for(unsigned bad=0;bad<4;++bad){auto u=coding(3);if(bad==0)++u.consumed_bytes;if(bad==1)std::get<MoviePictureCodingExtension>(u.payload).picture_structure=1;if(bad==2)std::get<MoviePictureCodingExtension>(u.payload).repeat_first_field=true;if(bad==3)u.bytes.push_back(0);check(!r.owner->coding_extension("key",r.id,u,r.f)&&r.f.kind==E::invalid_unit&&r.state()==before,"all typed/raw coding fields validated before clear");}
  r.bound(false);before=r.state();auto wrong=a;wrong.bytes[0]=7;check(!r.owner->append("key",r.id,MovieUserdataPrimaryKind::sequence,wrong,r.f)&&r.f.kind==E::invalid_unit&&r.state()==before,"disabled/nonpicture does not bypass input validation");
  std::exception_ptr ep;std::thread worker([&]{try{MovieUserdataRetentionFailure f;check(!r.owner->append("key",r.id,MovieUserdataPrimaryKind::picture,a,f)&&f.kind==E::wrong_thread,"foreign append");check(!r.owner->set_bound("key",r.id,true,f)&&f.kind==E::wrong_thread,"foreign binding");check(!r.owner->coding_extension("key",r.id,coding(3),f)&&f.kind==E::wrong_thread,"foreign coding");check(!r.owner->snapshot(f)&&f.kind==E::wrong_thread,"foreign snapshot");}catch(...){ep=std::current_exception();}});worker.join();if(ep)std::rethrow_exception(ep);check(r.state()==before,"foreign thread no mutation");}
 {Rig r;r.put(a);auto expected=r.state();NativeMovieUserdataRetention moved(std::move(*r.owner));check(!r.owner->snapshot(r.f)&&r.f.kind==E::invalid_owner,"moved snapshot invalid");check(!r.owner->append("key",r.id,MovieUserdataPrimaryKind::picture,a,r.f)&&r.f.kind==E::invalid_owner,"moved append invalid");check(!r.owner->set_bound("key",r.id,false,r.f)&&r.f.kind==E::invalid_owner,"moved binding invalid");check(!r.owner->coding_extension("key",r.id,coding(3),r.f)&&r.f.kind==E::invalid_owner,"moved coding invalid");moved=std::move(moved);auto self=moved.snapshot(r.f);check(self&&*self==expected,"selfmove retains identity and bytes");Rig replacement;*replacement.owner=std::move(moved);check(!moved.snapshot(r.f)&&moved.snapshot(r.f)==std::nullopt&&replacement.state()==expected,"move assignment invalidates donor and preserves full owner");}
 {Rig r;r.put(a);const auto before=r.state();for(int stage:{0,1}){allocate_after=stage;auto ok=r.owner->append("key",r.id,MovieUserdataPrimaryKind::picture,b,r.f);allocate_after=-1;check(!ok&&r.f.kind==E::allocation&&r.state()==before,"genuine staging-copy/reserve failures atomic and recoverable");}auto ext=coding(3);allocate_after=0;auto ok=r.owner->coding_extension("key",r.id,ext,r.f);allocate_after=-1;check(!ok&&r.f.kind==E::allocation&&r.state()==before,"coding validation allocation failure cannot clear state");allocate_after=0;auto copy=r.owner->snapshot(r.f);allocate_after=-1;check(!copy&&r.f.kind==E::allocation&&r.state()==before,"owned snapshot allocation failure no state change");r.put(b);}
 {MovieUserdataRetentionFailure f;auto id=std::make_shared<const MovieSourceObservationIdentity>();std::string key(200,'K');allocate_after=0;auto p=NativeMovieUserdataRetention::create(key,id,true,f);allocate_after=-1;check(!p&&f.kind==E::allocation,"genuine create key allocation");check(!NativeMovieUserdataRetention::create("",id,true,f)&&f.kind==E::invalid_source,"missing key");check(!NativeMovieUserdataRetention::create("k",{},true,f)&&f.kind==E::invalid_source,"missing identity");}
 {std::optional<MovieUserdataRetentionState> held;std::weak_ptr<const MovieSourceObservationIdentity> weak;{auto id=std::make_shared<const MovieSourceObservationIdentity>();weak=id;MovieUserdataRetentionFailure f;auto owner=NativeMovieUserdataRetention::create("held",id,true,f);auto input=userdata({0xff,0x80});check(owner&&owner->append("held",id,MovieUserdataPrimaryKind::picture,input,f),"held setup");held=owner->snapshot(f);}check(held&&held->bytes==Bytes({0,0,1,0xb2,0xff,0x80})&&!weak.expired(),"held owned bytes and source identity survive owner/input");held.reset();check(weak.expired(),"final identity released");}
 std::puts("PASS native current userdata retention phase/bytes/ownership; no callback or record binding");return 0;
}catch(const std::exception& e){allocate_after=-1;std::fprintf(stderr,"[userdata-retention] %s\n",e.what());return 1;}}
